-- JobSignal initial schema.
-- All timestamps are ISO-8601 UTC strings (e.g. 2026-10-15T12:00:00.000Z).
-- IDs are random text ids generated by the app.


-- ---------------------------------------------------------------- accounts

CREATE TABLE users (
  id               TEXT PRIMARY KEY,
  email            TEXT NOT NULL UNIQUE,
  name             TEXT,
  role             TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'admin')),
  prefs_json       TEXT NOT NULL DEFAULT '{}',
  created_at       TEXT NOT NULL,
  last_login_at    TEXT,
  email_verified_at TEXT,
  suspended_at     TEXT
);

CREATE TABLE sessions (
  id_hash      TEXT PRIMARY KEY,           -- sha-256 of the cookie value, never the raw token
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at   TEXT NOT NULL,
  expires_at   TEXT NOT NULL,
  last_seen_at TEXT NOT NULL,
  user_agent   TEXT
);
CREATE INDEX idx_sessions_user ON sessions(user_id);
CREATE INDEX idx_sessions_expires ON sessions(expires_at);

CREATE TABLE login_tokens (
  token_hash TEXT PRIMARY KEY,
  email      TEXT NOT NULL,
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  used_at    TEXT,
  ip_hash    TEXT
);
CREATE INDEX idx_login_tokens_email ON login_tokens(email, created_at);

CREATE TABLE subscriptions (
  id                       TEXT PRIMARY KEY,
  user_id                  TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
  plan                     TEXT NOT NULL,
  status                   TEXT NOT NULL CHECK (status IN ('active','trialing','past_due','canceled','incomplete','unpaid')),
  provider                 TEXT NOT NULL CHECK (provider IN ('stripe','dev')),
  provider_customer_id     TEXT,
  provider_subscription_id TEXT UNIQUE,
  current_period_end       TEXT,
  cancel_at_period_end     INTEGER NOT NULL DEFAULT 0,
  created_at               TEXT NOT NULL,
  updated_at               TEXT NOT NULL
);
CREATE INDEX idx_subscriptions_customer ON subscriptions(provider_customer_id);

CREATE TABLE payment_events (
  id           TEXT PRIMARY KEY,           -- provider event id, makes webhooks idempotent
  provider     TEXT NOT NULL,
  type         TEXT NOT NULL,
  received_at  TEXT NOT NULL,
  processed_at TEXT,
  error        TEXT
);

CREATE TABLE usage_records (
  id          TEXT PRIMARY KEY,
  subject_key TEXT NOT NULL,               -- 'user:<id>' or 'anon:<ip hash>'
  kind        TEXT NOT NULL,
  created_at  TEXT NOT NULL
);
CREATE INDEX idx_usage_subject ON usage_records(subject_key, kind, created_at);

CREATE TABLE rate_limits (
  key          TEXT PRIMARY KEY,
  window_start INTEGER NOT NULL,
  count        INTEGER NOT NULL
);

-- ---------------------------------------------------------------- companies

CREATE TABLE companies (
  id              TEXT PRIMARY KEY,
  slug            TEXT NOT NULL UNIQUE,
  name            TEXT NOT NULL,
  normalized_name TEXT NOT NULL,
  domain          TEXT,
  cik             TEXT,
  ticker          TEXT,
  sec_checked_at  TEXT,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE INDEX idx_companies_normalized ON companies(normalized_name);
CREATE INDEX idx_companies_domain ON companies(domain);
CREATE UNIQUE INDEX idx_companies_cik ON companies(cik) WHERE cik IS NOT NULL;

-- One company can be reached through several names and job boards.
CREATE TABLE company_aliases (
  id               TEXT PRIMARY KEY,
  company_id       TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  kind             TEXT NOT NULL CHECK (kind IN ('name','ats_board','domain')),
  value            TEXT NOT NULL,          -- normalized name, 'greenhouse:airbnb', or 'airbnb.com'
  display          TEXT,
  source           TEXT NOT NULL,
  created_at       TEXT NOT NULL,
  UNIQUE (kind, value, company_id)
);
CREATE INDEX idx_aliases_lookup ON company_aliases(kind, value);
-- A job board token can only belong to one company.
CREATE UNIQUE INDEX idx_aliases_board ON company_aliases(value) WHERE kind = 'ats_board';

CREATE TABLE company_events (
  id            TEXT PRIMARY KEY,
  company_id    TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  kind          TEXT NOT NULL,             -- warn_notice, sec_restructuring, sec_bankruptcy, going_concern, acquisition, ...
  event_date    TEXT NOT NULL,
  title         TEXT NOT NULL,
  detail        TEXT,
  magnitude     INTEGER,                   -- e.g. employees affected, when the source states it
  source_name   TEXT NOT NULL,
  source_url    TEXT,
  reliability   TEXT NOT NULL CHECK (reliability IN ('official','reported','derived')),
  match_quality TEXT NOT NULL CHECK (match_quality IN ('exact','probable')),
  external_id   TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  hidden_at     TEXT,                      -- admins can hide a wrongly matched event
  UNIQUE (company_id, kind, external_id)
);
CREATE INDEX idx_events_company ON company_events(company_id, event_date);

CREATE TABLE warn_notices (
  id                  TEXT PRIMARY KEY,
  state               TEXT NOT NULL,
  source_record_id    TEXT NOT NULL,
  employer            TEXT NOT NULL,
  employer_normalized TEXT NOT NULL,
  notice_date         TEXT,
  effective_date      TEXT,
  city                TEXT,
  county              TEXT,
  employees_affected  INTEGER,
  layoff_type         TEXT,
  source_url          TEXT NOT NULL,
  ingested_at         TEXT NOT NULL,
  UNIQUE (state, source_record_id)
);
CREATE INDEX idx_warn_employer ON warn_notices(employer_normalized);
CREATE INDEX idx_warn_date ON warn_notices(notice_date);

-- ---------------------------------------------------------------- jobs

CREATE TABLE jobs (
  id                TEXT PRIMARY KEY,
  canonical_key     TEXT NOT NULL UNIQUE,  -- 'greenhouse:airbnb:8184174', 'manual:<hash>', ...
  company_id        TEXT REFERENCES companies(id) ON DELETE SET NULL,
  source_kind       TEXT NOT NULL,         -- greenhouse, lever, ashby, jsonld, manual
  source_url        TEXT,
  apply_url         TEXT,
  title             TEXT NOT NULL,
  location          TEXT,
  employment_type   TEXT,
  compensation_text TEXT,
  published_at      TEXT,                  -- only when the source states a publish/creation date
  source_updated_at TEXT,                  -- 'last updated' from the source. NOT a creation date.
  valid_through     TEXT,
  fingerprint       TEXT NOT NULL,         -- company + normalized title + location
  status            TEXT NOT NULL DEFAULT 'unknown' CHECK (status IN ('open','closed','unknown')),
  first_seen_at     TEXT NOT NULL,         -- first time JobSignal saw it, not when it was posted
  last_seen_at      TEXT NOT NULL,
  last_checked_at   TEXT NOT NULL,
  closed_at         TEXT,
  reopened_count    INTEGER NOT NULL DEFAULT 0,
  content_hash      TEXT,
  created_at        TEXT NOT NULL
);
CREATE INDEX idx_jobs_fingerprint ON jobs(fingerprint);
CREATE INDEX idx_jobs_company ON jobs(company_id);
CREATE INDEX idx_jobs_checked ON jobs(last_checked_at);

CREATE TABLE job_observations (
  id           TEXT PRIMARY KEY,
  job_id       TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
  observed_at  TEXT NOT NULL,
  result       TEXT NOT NULL CHECK (result IN ('found','missing','error','manual')),
  content_hash TEXT,
  via          TEXT NOT NULL               -- 'analysis', 'monitor', 'board_scan'
);
CREATE INDEX idx_observations_job ON job_observations(job_id, observed_at);

-- Description text is kept only when it changes, so we can show diffs.
CREATE TABLE job_versions (
  id               TEXT PRIMARY KEY,
  job_id           TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
  content_hash     TEXT NOT NULL,
  title            TEXT NOT NULL,
  description_text TEXT NOT NULL,
  observed_at      TEXT NOT NULL,
  UNIQUE (job_id, content_hash)
);

-- ---------------------------------------------------------------- analyses

CREATE TABLE analyses (
  id               TEXT PRIMARY KEY,
  job_id           TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
  company_id       TEXT REFERENCES companies(id) ON DELETE SET NULL,
  scoring_version  TEXT NOT NULL,
  input_kind       TEXT NOT NULL CHECK (input_kind IN ('url','manual')),
  posting_label    TEXT NOT NULL,
  employer_label   TEXT NOT NULL,
  confidence_label TEXT NOT NULL,
  posting_score    REAL NOT NULL,
  employer_score   REAL NOT NULL,
  confidence_score REAL NOT NULL,
  report_json      TEXT NOT NULL,          -- full snapshot of what the user saw
  created_at       TEXT NOT NULL
);
CREATE INDEX idx_analyses_job ON analyses(job_id, created_at);
CREATE INDEX idx_analyses_company ON analyses(company_id, created_at);

CREATE TABLE analysis_findings (
  id          TEXT PRIMARY KEY,
  analysis_id TEXT NOT NULL REFERENCES analyses(id) ON DELETE CASCADE,
  rule_id     TEXT NOT NULL,
  dimension   TEXT NOT NULL,
  polarity    TEXT NOT NULL,
  weight      REAL NOT NULL,
  title       TEXT NOT NULL
);
CREATE INDEX idx_findings_analysis ON analysis_findings(analysis_id);
CREATE INDEX idx_findings_rule ON analysis_findings(rule_id);

-- A person's copy of an analysis. Holds who ran it and whether it is shared.
CREATE TABLE reports (
  id          TEXT PRIMARY KEY,
  slug        TEXT NOT NULL UNIQUE,
  analysis_id TEXT NOT NULL REFERENCES analyses(id) ON DELETE CASCADE,
  user_id     TEXT REFERENCES users(id) ON DELETE CASCADE,
  anon_id     TEXT,                        -- random cookie id for visitors without an account
  is_public   INTEGER NOT NULL DEFAULT 0,
  created_at  TEXT NOT NULL
);
CREATE INDEX idx_reports_user ON reports(user_id, created_at);
CREATE INDEX idx_reports_anon ON reports(anon_id);

-- ---------------------------------------------------------------- user data

CREATE TABLE saved_jobs (
  id               TEXT PRIMARY KEY,
  user_id          TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  job_id           TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
  report_id        TEXT REFERENCES reports(id) ON DELETE SET NULL,
  status           TEXT NOT NULL DEFAULT 'interested'
                   CHECK (status IN ('interested','applied','interviewing','offer','rejected','no_response','withdrawn')),
  notes            TEXT NOT NULL DEFAULT '',
  deadline         TEXT,
  remind_at        TEXT,
  reminder_sent_at TEXT,
  checklist_json   TEXT NOT NULL DEFAULT '{}',
  monitor          INTEGER NOT NULL DEFAULT 0,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  UNIQUE (user_id, job_id)
);
CREATE INDEX idx_saved_jobs_monitor ON saved_jobs(monitor, job_id);
CREATE INDEX idx_saved_jobs_remind ON saved_jobs(remind_at);

CREATE TABLE saved_companies (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  monitor    INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  UNIQUE (user_id, company_id)
);
CREATE INDEX idx_saved_companies_company ON saved_companies(company_id);

CREATE TABLE notifications (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind       TEXT NOT NULL,
  title      TEXT NOT NULL,
  body       TEXT NOT NULL,
  link       TEXT,
  dedupe_key TEXT NOT NULL,
  read_at    TEXT,
  emailed_at TEXT,
  created_at TEXT NOT NULL,
  UNIQUE (user_id, dedupe_key)
);
CREATE INDEX idx_notifications_user ON notifications(user_id, created_at);

CREATE TABLE comparisons (
  id              TEXT PRIMARY KEY,
  user_id         TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name            TEXT NOT NULL,
  report_ids_json TEXT NOT NULL,
  weights_json    TEXT NOT NULL,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE INDEX idx_comparisons_user ON comparisons(user_id, updated_at);

CREATE TABLE saved_filters (
  id           TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  scope        TEXT NOT NULL,
  name         TEXT NOT NULL,
  filters_json TEXT NOT NULL,
  created_at   TEXT NOT NULL
);
CREATE INDEX idx_saved_filters_user ON saved_filters(user_id, scope);

-- ---------------------------------------------------------------- trust & ops

CREATE TABLE feedback (
  id         TEXT PRIMARY KEY,
  report_id  TEXT REFERENCES reports(id) ON DELETE SET NULL,
  user_id    TEXT REFERENCES users(id) ON DELETE SET NULL,
  helpful    INTEGER,
  comment    TEXT,
  created_at TEXT NOT NULL
);

-- "This is wrong" reports from users or companies.
CREATE TABLE flags (
  id              TEXT PRIMARY KEY,
  report_id       TEXT REFERENCES reports(id) ON DELETE SET NULL,
  company_id      TEXT REFERENCES companies(id) ON DELETE SET NULL,
  user_id         TEXT REFERENCES users(id) ON DELETE SET NULL,
  contact_email   TEXT,
  reason          TEXT NOT NULL,
  detail          TEXT NOT NULL,
  status          TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','resolved','dismissed')),
  resolution_note TEXT,
  created_at      TEXT NOT NULL,
  resolved_at     TEXT,
  resolved_by     TEXT
);
CREATE INDEX idx_flags_status ON flags(status, created_at);

CREATE TABLE fetch_cache (
  key          TEXT PRIMARY KEY,
  status       INTEGER NOT NULL,
  body         TEXT NOT NULL,
  fetched_at   TEXT NOT NULL,
  expires_at   TEXT NOT NULL
);
CREATE INDEX idx_fetch_cache_expires ON fetch_cache(expires_at);

CREATE TABLE provider_runs (
  id          TEXT PRIMARY KEY,
  provider    TEXT NOT NULL,
  operation   TEXT NOT NULL,
  ok          INTEGER NOT NULL,
  status_code INTEGER,
  duration_ms INTEGER NOT NULL,
  error       TEXT,
  created_at  TEXT NOT NULL
);
CREATE INDEX idx_provider_runs ON provider_runs(provider, created_at);

CREATE TABLE job_runs (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  started_at  TEXT NOT NULL,
  finished_at TEXT,
  ok          INTEGER,
  summary     TEXT,
  error       TEXT
);
CREATE INDEX idx_job_runs ON job_runs(name, started_at);

CREATE TABLE feature_flags (
  key         TEXT PRIMARY KEY,
  enabled     INTEGER NOT NULL,
  description TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);

CREATE TABLE announcements (
  id         TEXT PRIMARY KEY,
  message    TEXT NOT NULL,
  level      TEXT NOT NULL DEFAULT 'info' CHECK (level IN ('info','warning')),
  active     INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  expires_at TEXT
);

CREATE TABLE admin_audit_logs (
  id            TEXT PRIMARY KEY,
  admin_user_id TEXT,
  action        TEXT NOT NULL,
  target        TEXT,
  detail        TEXT,
  created_at    TEXT NOT NULL
);
CREATE INDEX idx_audit_created ON admin_audit_logs(created_at);

